from functools import Reduce
def factorial(n):
  if n == 0:
    return 1
  else:
    return n * factorial(n-1)
def comb(n, h):
  memo = {}
  if (n,h) in memo:
    return memo[(n,h)]
  else:
    if n == 0 or h == 0:
      result = 1
    else:
      for i in range(h, n+1):
        result += comb(i-1, h-1) * factorial(n-i)
    memo[(n,h)] = result
    return result
n,h=map(int,raw_input().split())
print comb(n,h)-comb(n,max(0,h-1))

